    strategy_aggressive_desc: '적의 노드를 빠르게 점령하고 중앙을 장악하는 데 집중하는 프로토콜입니다. 자신의 사이드가 노출되는 한이 있더라도 높은 리스크를 지고 연속 콤보를 유도합니다.',
    strategy_defensive_desc: '보안 최우선 프로토콜입니다. 자신의 카드가 절대 뒤집히지 않도록 구석과 가장자리 선점을 최우선으로 하며, 빈틈없는 방어벽을 천천히 구축하여 상대를 질식시킵니다.',
    strategy_random_desc: '엔트로피 프로토콜입니다. AI가 매 수마다 논리와 무관하게 완전히 무작위로 위치를 선택합니다. 상대방의 패턴 학습을 방해하거나 혼란을 줄 때 유용합니다.',
    strategy_auto_desc: '학습된 가중치를 기반으로 남은 턴과 점수차를 분석합니다. 유리할 때는 방어형으로 굳히기, 불리할 때는 공격형으로 역전의 발판을 마련하며 능동적으로 태세를 전환합니다.',
    strategy_balanced_pros: '어떤 덱이나 상황에서도 평균 이상의 안정적인 승률을 기대할 수 있으며 상대의 실수를 놓치지 않음',
    strategy_balanced_cons: '극단적인 방어 전술이나 파상공세를 펼치는 특화 덱 상대로는 돌파력이 부족하여 교착상태에 빠지기 쉬움',
    strategy_aggressive_pros: '초반 기세 제압이 확실하며, 상대가 중앙을 내준 사이 순식간에 막대한 점수를 획득하여 압도적 승리 쟁취',
    strategy_aggressive_cons: '뒷면 숫자가 낮은 방어 공백이 필연적으로 발생하여, 후반부에 역전의 빌미를 쉽게 제공함',
    strategy_defensive_pros: '한 번 점유한 거점을 절대 내어주지 않아 후반부 안정성이 극도로 높고, 상대에게 심리적 압박감을 부여',
    strategy_defensive_cons: '게임 초반에 주도권을 잃고 구석을 선점당하면 돌파 수단이 적어 그대로 패배할 확률이 수직 상승함',
    strategy_auto_pros: '전황 변화에 즉각적으로 대응하여 리스크 관리를 철저히 하고, 인간 고수의 템포 조절과 가장 흡사함',
    strategy_auto_cons: '단순명료한 최선수(Greedy) 대신 지나치게 계산적인 차선수를 택하다가 허무하게 빈틈을 내줄 수 있음',
    strategy_random_pros: '상대방이 AI의 다음 전략을 전혀 예측할 수 없어 엄청난 심리적 혼란과 판단 착오를 유도할 수 있음',
    strategy_random_cons: '최소한의 전술적 시너지가 없어 단순히 자멸할 확률이 높고, 승리 가능성이 전적으로 운에 좌우됨',
