    wiki_how_to_play_1: 'SNSHero.com은 전술적인 1v1 카드 배틀 게임입니다. 두 플레이어는 각각 5장의 활성 덱을 가지고 시작합니다. 번갈아가며 3x3 보드에 카드를 배치합니다.',
