    seo_title_home: "SNSHero - 생성형 AI 카드 배틀 게임",
    seo_desc_home: "복잡한 클라이언트 설치나 가입 절차 없이 클릭 한 번으로 즐기는 인공지능(AI) 웹 카드 게임 'SNS히어로'를 만나보세요! 번거로운 과정 없이 구글 계정 연동만으로 즉시 게임 로비에 접속할 수 있습니다. 지금 로그인하시는 모든 분께 초기 정착을 위한 1,000 SNS 포인트를 즉시 지급해 드립니다. 또한 최대 100회의 무료 뽑기 기회를 제공하여 110여 종의 귀여운 일러스트 카드를 부담 없이 수집할 수 있습니다. 타인과의 피 말리는 경쟁 스트레스는 내려놓고, 나의 페이스에 맞춰 AI 적수와 편안하게 실시간 대전을 즐겨보세요. 비트코인(BTC), 이더리움(ETH), USDC 등 다양한 암호화폐 결제를 지원하여 전 세계 어디서든 자유롭고 편리한 인앱 결제가 가능합니다. PC와 스마트폰 등 웹 브라우저가 있는 기기라면 언제 어디서든 심리스하게 나만의 덱을 완성할 수 있습니다. 압도적인 보상과 혜택이 기다리는 SNSHero.com에 지금 바로 접속해 보세요!",
