  mode_treasure: '보물대전',
  mode_ai_battle_guide: 'AI가 조종하는 로봇과 1:1 카드배틀을 진행합니다.\n3x3 보드에 카드를 배치해 동서남북 스탯으로 상대 카드를 뒤집으세요.\n자동전투 모드로 연속 플레이도 가능합니다.',
  mode_tournament_guide: '8명의 참가자가 토너먼트 방식으로 대결합니다.\n총 3라운드(8강→4강→결승)를 진행하며 우승 시 큰 보상을 획득할 수 있습니다.',
  mode_story_guide: '시나리오를 따라 진행하는 스토리 모드입니다.\n각 액트별로 점점 강해지는 상대와 대결하며 스토리를 클리어하세요.',
  mode_boss_guide: '강력한 보스 몬스터와 1:1로 대결합니다.\n일반 카드보다 훨씬 높은 스탯을 가진 보스를 상대로 전략적인 플레이가 필요합니다.',
  mode_dungeon_guide: '필드에서 몬스터를 찾아 전투하는 던전 탐험 모드입니다.\n몬스터 처치 시 보상과 경험치를 획득할 수 있습니다.',
  mode_defense_guide: '타워 디펜스 스타일의 방어 모드입니다.\n라인마다 카드를 배치해 몰려오는 적을 막으세요. 라운드가 올라갈수록 난이도가 증가합니다.',
  mode_running_guide: '실제 GPS 위치기반 러닝 게임 모드입니다.\n달리면서 칼로리를 소모하고 SNS 포인트를 획득하세요.',
  mode_treasure_guide: '내 위치 주변 100m 이내의 보물상자를 찾아 카드를 획득하세요!',
  mode_matgo: '맞고대전',
  mode_matgo_guide: '110장의 카드로 진행하는 고스톱 룰 카드 배틀입니다.\n같은 종족의 카드를 겹치거나 빈 칸에 배치하여 짝을 맞춰 1점을 획득하세요.\n5턴 후 점수가 높은 플레이어가 승리합니다.',
  mode_snake: '스네이크대전',
  mode_snake_guide: '내 마이덱 카드 5장으로 시작하는 카드 스네이크 배틀입니다.\n카드 먹이와 상대 스네이크 조각을 먹으면 110장 카드 순서대로 몸이 길어집니다.\nAI와 경쟁하고 같은 접속 환경의 실시간 플레이어도 함께 표시됩니다.',
  snake_subtitle: '마이덱 카드로 길어지는 실시간 카드 스네이크',
