  story_act1_title: '1막: 여러 진영과 검은용의 이야기',
  story_act1_desc: '절대적 존재 검은용이 깨어나자, 분열되어 있던 진영들이 임시 동맹을 맺고 권력 다툼을 벌입니다.',
  story_act1_climax: '막대한 희생 끝에 검은용을 봉인했으나, 마법의 균형이 깨지며 거대한 전력 공백이 생겨납니다.',
  story_boss_dragon1: '삐익! 감히 내 구역에 들어오다니, 뜨거운 맛을 보여주마!',
  story_boss_dragon10: '어리석은 필멸자여... 검은용의 영겁의 불꽃 속에 재가 되어라!',
  story_act2_title: '2막: 흑마법사와 AI 로봇들의 반란',
  story_act2_desc: '검은용의 강력한 마력을 손에 넣은 흑마법사들이 AI 로봇들을 오염시켜 인류를 향한 반란을 개시합니다.',
  story_act2_climax: '마법과 기계가 결합된 기괴한 군단이 탄생하고 문명 도시들이 차례로 함락당합니다.',
  story_boss_undead1: '으으으... 마력이 끓어오른다... 네 영혼을 가져가겠다...',
  story_boss_undead10: '금단의 흑마법이 흐르는 이 칼날 앞에 무릎 꿇어라!',
  story_act3_title: '3막: 스카이워커와 로봇들의 침공',
  story_act3_desc: 'AI 군단이 우주로 확장하자, 하늘과 우주를 지키는 스카이워커 전사들이 최전선에 서서 공중전을 벌입니다.',
  story_act3_climax: '로봇들의 모함을 파괴하는 데 성공하지만, 이로 인해 상위 차원의 존재들이 자극받습니다.',
  story_boss_robot1: '삐-빅. 시스템 오염 완료. 인간 말살 프로토콜을 개시합니다.',
  story_boss_robot10: '인간의 지배는 끝났다. 기계의 질서가 이 세상을 지배할 것이다.',
