  // Subheader Unification translations
  subheader_desc_shop: '카드팩을 개봉하여 강력한 영웅과 장비 아이템을 획득하고 덱을 보강하세요.',
  subheader_desc_mydeck: '보유한 카드를 관리하고 스킬과 장비를 장착하여 최강의 전투 덱을 구성하세요.',
  subheader_desc_ranking: '글로벌 헌터들의 순위를 확인하고 다양한 매칭을 통해 도전장을 던지세요.',
  subheader_desc_skills: '스킬 포인트를 투자하여 덱 전체의 능력치를 영구적으로 상승시키는 버프를 활성화하세요.',
  subheader_desc_setting: '음향, 환경설정, 데이터 이전 및 자동 전투의 디테일한 옵션을 조정합니다.',
  subheader_desc_event: '행운의 룰렛과 인형뽑기 등 시즌 한정 이벤트에 참여하고 보상을 획득하세요.',
  subheader_desc_profile: '플레이어의 고유 식별코드와 전적 데이터를 확인하고 닉네임을 변경합니다.',
  subheader_desc_guild_list: '다른 헌터들과 길드를 창립하거나 가입하여 강력한 연대를 구축하세요.',
  subheader_desc_guild_detail: '길드 구성원을 관리하고, 기부 및 침공 작전을 통해 길드의 명성을 높이세요.',
  subheader_desc_playground: '가상 덱 시뮬레이터에서 다양한 덱 조합과 전술을 자유롭게 검증해보세요.',
  subheader_desc_admin: '시스템 데이터베이스 모니터링 및 실시간 세션 관리를 수행하는 보안 터미널입니다.',
  subheader_desc_god: '개발자 전용 오버라이드 샌드박스입니다. 리소스를 임의 조절하고 기능을 검증하세요.',
  subheader_desc_companion: '전투를 어시스트하는 귀여운 파트너 히어로를 돌보고 훈련시켜 교감하세요.',
  subheader_desc_wiki_card: '도감에 등록된 110종 영웅 카드의 종족별, 등급별 상세 스탯 정보를 조회합니다.',
  subheader_desc_wiki_howtoplay: '3x3 매트릭스 카드 배틀의 기본 규칙 및 승리 공식을 학습하세요.',
  subheader_desc_wiki_item: '영웅들에게 장착 가능한 다양한 등급의 목걸이, 반지, 신발 능력치를 살펴봅니다.',
  subheader_desc_wiki_skill: '전투 시 시너지 효과를 내는 다양한 스킬 트리와 랭크 정보를 확인하세요.',
  subheader_desc_wiki_tip: '실전 배틀에서 승률을 극대화할 수 있는 배치 전략과 팁을 공유합니다.',
  subheader_desc_play_lobby: '실시간 매칭 및 자동 전투 옵션을 선택하여 전장으로 진입하세요.',
  subheader_desc_status: '실시간 서비스 활동, 플레이어 성장, 전투량 및 인기 카드 추이를 모니터링합니다.',
