    patch_w2_bugfix_multiplayer_desc: '상대 매칭 대기 중 30초 이상 응답이 없으면 자동 취소되도록 타임아웃 처리를 추가했습니다.',
    patch_w2_balance_cards_title: '카드 밸런스 조정 (4종)',
    patch_w2_balance_cards_desc: '카드 #1, #5, #12, #23의 스탯이 과도하게 높다고 판단되어 Top/Right 스탯을 소폭 하향 조정했습니다.',
    patch_w2_balance_gacha_title: '가챠 확률 소폭 조정',
    patch_w2_balance_gacha_desc: '플래티넘 등급 출현 확률을 1.2%에서 1.5%로 상향했습니다. 고급 카드 획득 기회가 늘어납니다.',
    patch_w2_content_story_title: '시즌1 신규 웹툰 에피소드 3화 추가',
    patch_w2_content_story_desc: '시즌1 스토리 라인의 웹툰 에피소드 3화가 추가되었습니다. 웹툰 허브에서 감상하세요.',
    patch_w2_content_seasonhub_title: '시즌 허브 미션 보상 강화',
    patch_w2_content_seasonhub_desc: '데일리/위클리 미션 완료 보상이 강화되고, 시즌 미션 진행률 표시 UI가 개선되었습니다.',
    patch_w2_known_ios_title: 'iOS 17 Safari 웹푸시 알림 미지원',
    patch_w2_known_ios_desc: 'iOS 17 이하 Safari 브라우저에서는 웹푸시 알림이 지원되지 않습니다. iOS 18 이상 또는 Chrome 사용을 권장합니다.',
    patch_w3_content_cardpack_title: '신규 카드팩 「칠흑의 기사단」 출시',
    patch_w3_content_cardpack_desc: '한정 카드 5종이 포함된 신규 카드팩이 상점에 추가되었습니다. 2주간 한정 판매됩니다.',
    patch_w3_content_guildraid_title: '길드 레이드 베타 오픈',
    patch_w3_content_guildraid_desc: '길드원과 함께 보스에 도전하는 길드 레이드 콘텐츠가 베타 버전으로 오픈됩니다. 커뮤니티 화면에서 참여하세요.',
    patch_w3_balance_ranked_title: '랭킹전 매치메이킹 알고리즘 개선',
    patch_w3_balance_ranked_desc: '비슷한 실력의 상대와 매칭되도록 레이팅 기반 매치메이킹 정밀도를 개선했습니다.',
    patch_w3_bugfix_ui_title: '갤럭시 폴드 시리즈 UI 깨짐 수정',
    patch_w3_bugfix_ui_desc: '폴더블 기기에서 UI 요소가 화면 비율에 맞지 않게 표시되던 문제를 수정했습니다.',
    patch_w3_bugfix_sound_title: '배경음악 반복 재생 시 끊김 현상 수정',
    patch_w3_bugfix_sound_desc: '일부 브라우저에서 배경음악이 반복될 때 발생하던 짧은 무음 구간을 제거했습니다.',
    patch_w3_known_lowend_title: '저사양 모드에서 일부 애니메이션 생략 안내',
    patch_w3_known_lowend_desc: '저사양 모드 활성화 시 카드 획득 연출 등 일부 애니메이션이 생략됩니다. 설정에서 저사양 모드를 해제하면 모든 연출을 감상할 수 있습니다.',

